mapper.select:
select marketing_spu_id as id, count(*) as count from marketing_product_sku where is_deleted = 0 and marketing_spu_id in
#{marketingSpuId}
group by marketing_spu_id

select marketing_spu_id as id, sum(stock) as count from marketing_product_sku where is_deleted = 0 and marketing_spu_id in
#{marketingSpuId}
group by marketing_spu_id

select marketing_spu_id as id, min(buyout_amount) as minPrice, max(buyout_amount) as maxPrice from marketing_product_sku where is_deleted = 0 and marketing_spu_id in
#{marketingSpuId}
group by marketing_spu_id

select sku.id, sku.daily_rent, spu.name from marketing_product_sku sku left join marketing_product_spu spu on sku.marketing_spu_id = spu.id where sku.is_deleted = 0 and spu.is_deleted = 0 and spu.shelves_status = 1
and spu.name like concat('%', #{name}, '%')
and sku.id in
#{id}
order by sku.create_time desc limit #{offset}, #{pageSize}
